-- Marketing- en salesacties: de checklist op /dashboard/groei.
-- Alleen acties staan hier. Cijfers (leads, reviews, nieuwsbrief, prospects,
-- campagnes, portaal, offertes, omzet) worden live uit de bestaande tabellen
-- gelezen en niet gekopieerd. Veilig om opnieuw te draaien: bestaande acties
-- (zelfde sleutel) blijven ongemoeid.

create table if not exists public.marketing_acties (
  id uuid primary key default gen_random_uuid(),
  sleutel text unique,
  titel text not null,
  omschrijving text,
  categorie text not null default 'website'
    check (categorie in ('fundament','website','seo','bewijs','content','sales','klantbinding','netwerk','systeem')),
  eigenaar text not null default 'jessi' check (eigenaar in ('tim','jessi','claude')),
  prioriteit smallint not null default 2 check (prioriteit between 1 and 3),
  status text not null default 'open' check (status in ('open','bezig','klaar','geparkeerd')),
  deadline date,
  kpi text,
  notities text,
  bron text,
  volgorde integer not null default 0,
  afgerond_op timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.marketing_acties enable row level security;
-- Geen policies: alleen het KMS (service role) leest en schrijft.

create index if not exists marketing_acties_status_idx on public.marketing_acties (status, prioriteit, volgorde);

on conflict (sleutel) do nothing;
