insert into public.marketing_acties (sleutel, titel, omschrijving, categorie, eigenaar, prioriteit, status, kpi, bron, volgorde, afgerond_op) values
  ('zet-de-nieuwe-site-live-op-www-frederiksbedrijfskleding-nl', 'Zet de nieuwe site live op www.frederiksbedrijfskleding.nl', 'Het domein toont nog de oude site; de canonical, 606 pagina''s, sitemap en alle SEO-structuur tellen pas mee na de domeinkoppeling in Vercel. Blokkeert ook de QR-brieven en de inloglinks.', 'fundament', 'tim', 1, 'open', 'leads_30d', 'marktanalyse stap 1, seo-geo-plan week 1, concurrentieanalyse 6 okt', 10, null),
  ('vergelijk-oude-url-s-met-nieuwe-en-zet-301-redirects', 'Vergelijk oude URL''s met nieuwe en zet 301-redirects', 'De oude site staat al #2 op ''bedrijfskleding Achterhoek'' en #3 op ''bedrijfskleding Hengelo Gelderland''; zonder redirects gaat die positie verloren bij de overstap.', 'fundament', 'tim', 1, 'open', 'leads_30d', 'seo-geo-plan week 1', 20, null),
  ('richt-resend-in-en-verifieer-het-maildomein', 'Richt Resend in en verifieer het maildomein', 'Zonder RESEND_API_KEY en RESEND_FROM gaan uitnodigingen, bevestigingen, nieuwsbrieven, campagnes en NPS-mails niet de deur uit. Domein verifiëren via DNS.', 'fundament', 'tim', 1, 'open', 'campagnes_actief', 'portaal-toegang-proces, feedback Jessi 2 okt, herontwerp 4 okt', 30, null),
  ('zet-supabase-custom-smtp-en-de-nederlandse-inlogmail-aan', 'Zet Supabase custom SMTP en de Nederlandse inlogmail aan', 'Standaard Supabase-mail gaat alleen naar teamleden, max 2 per uur; klanten kunnen pas inloggen met SMTP via Resend en de template magic-link-nl.html.', 'fundament', 'tim', 1, 'open', 'portaal_klanten', 'portaal-toegang-proces', 40, null),
  ('koppel-google-search-console-en-bing-webmaster-tools', 'Koppel Google Search Console en Bing Webmaster Tools', 'Sitemap indienen op het echte domein; Bing voedt de zoekresultaten van ChatGPT. Daarna maandelijks posities volgen voor ''bedrijfskleding/werkkleding [plaats]'' over 28 plaatsen.', 'fundament', 'tim', 1, 'open', 'leads_30d', 'seo-geo-plan week 1', 50, null),
  ('optimaliseer-het-google-bedrijfsprofiel', 'Optimaliseer het Google Bedrijfsprofiel', 'Hoofdcategorie ''Leverancier van werkkleding'', extra bedrukkerij en borduurservice, servicegebied met 28 plaatsen, pin op de Brouwersmolen, consequent ''Hengelo Gld'', diensten, producten en 20+ foto''s. Bepaalt het grootste deel van de Maps-ranking.', 'fundament', 'tim', 1, 'open', 'leads_30d', 'seo-geo-plan week 1-2, marktanalyse regio', 60, null),
  ('vul-de-ga4-id-in-en-controleer-de-cookie-consent', 'Vul de GA4-ID in en controleer de cookie-consent', 'Zonder meting is niet te zien welke kanalen leads opleveren; Analytics en ConsentBanner staan klaar, de ID ontbreekt nog.', 'fundament', 'tim', 2, 'open', 'leads_30d', 'go-live checklist', 70, null),
  ('laat-frederiksmannenmode-nl-werkkleding-doorverwijzen', 'Laat frederiksmannenmode.nl/werkkleding doorverwijzen', 'Die pagina concurreert met frederiksbedrijfskleding.nl om dezelfde werkkledingtermen en verdeelt de autoriteit.', 'seo', 'tim', 2, 'open', 'leads_30d', 'marktanalyse regio', 80, null),
  ('zet-citaties-met-exact-dezelfde-naw-gegevens', 'Zet citaties met exact dezelfde NAW-gegevens', 'Telefoonboek.nl claimen, Apple Business Connect, Bing Places, Cylex, Openingstijden.nl, KvK en De Telefoongids met Kruisbergseweg 9, 7255 AG Hengelo Gld, 06 15 21 50 29.', 'seo', 'tim', 2, 'open', 'leads_30d', 'seo-geo-plan week 2-4', 90, null),
  ('vul-de-facebook-pagina-en-koppel-hem-in-de-site', 'Vul de Facebook-pagina en koppel hem in de site', 'site.social.facebook is nog leeg; een ingevulde pagina telt als citatie en vertrouwenssignaal.', 'seo', 'jessi', 3, 'open', null, 'seo-geo-plan week 2-4', 100, null),
  ('start-het-recensie-offensief-na-elke-levering', 'Start het recensie-offensief na elke levering', 'Doel 25 echte Google-reviews in 4 maanden (circa 2 per week), op termijn van 8 naar 40. Vraag elke klant via de vaste link en laat plaats en type kleding noemen; Proforto heeft er 1.561.', 'bewijs', 'jessi', 1, 'open', 'reviews_aantal', 'marktanalyse stap 3, seo-geo-plan, concurrentieanalyse 6 okt', 110, null),
  ('reageer-op-elke-review-binnen-een-werkdag', 'Reageer op elke review binnen een werkdag', 'Reacties op reviews wegen mee in de lokale ranking en laten zien dat er een persoon achter zit.', 'bewijs', 'jessi', 2, 'open', 'reviews_score', 'seo-geo-plan doorlopend', 120, null),
  ('automatische-review-en-nps-vraag-na-levering', 'Automatische review- en NPS-vraag na levering', 'Reviews en NPS gaan automatisch na verzonden, factureren of afgerond (niet na annulering), met aggregateRating pas vanaf 5 antwoorden.', 'bewijs', 'claude', 1, 'klaar', 'reviews_aantal', 'ronde 6', 130, now()),
  ('lever-drie-klantcases-met-naam-plaats-en-foto', 'Lever drie klantcases met naam, plaats en foto', 'Nu nul cases; dat is het sterkste bewijs voor Google, LLM''s en kopers. Kies drie klanten uit verschillende branches en plaatsen.', 'bewijs', 'jessi', 1, 'open', 'lead_naar_offerte', 'seo-geo-plan, concurrentieanalyse 6 okt', 140, null),
  ('bouw-casepagina-s-gekoppeld-aan-plaats-en-branche', 'Bouw casepagina''s gekoppeld aan plaats en branche', 'Elke case als eigen pagina, gelinkt vanaf de bijbehorende plaats- en branchepagina en de referentiepagina, met JSON-LD.', 'bewijs', 'claude', 2, 'open', 'lead_naar_offerte', 'seo-geo-plan maand 1-4', 150, null),
  ('plan-een-fotodag-langs-drie-of-vier-klanten-in-de-regio', 'Plan een fotodag langs drie of vier klanten in de regio', 'Mensen in Frederiks-kleding op hun eigen werkvloer met hun logo, plus macro-opnames van naden. Vervangt de kleine sectorfoto''s en de stockachtige sportfoto; dit kan een landelijke webshop niet namaken.', 'bewijs', 'jessi', 2, 'open', 'lead_naar_offerte', 'website-redesign, herontwerp 4 okt', 160, null),
  ('lever-een-portretfoto-van-jessi', 'Lever een portretfoto van Jessi', 'Nodig voor het Jessi-paneel; een gezicht bij de 24-uursbelofte is wat landelijke webshops niet hebben.', 'bewijs', 'jessi', 2, 'open', 'lead_naar_offerte', 'ronde 6, herontwerp', 170, null),
  ('bevestig-of-merklogo-s-als-dealer-gevoerd-mogen-worden', 'Bevestig of merklogo''s als dealer gevoerd mogen worden', 'De merkstrip wacht op toestemming; officiële merklogo''s verhogen het vertrouwen.', 'bewijs', 'jessi', 3, 'open', null, 'herontwerp 4 okt', 180, null),
  ('neem-een-demovideo-van-1-a-2-minuten-op', 'Neem een demovideo van 1 à 2 minuten op', 'Iedereen heeft een klantportaal, niemand laat het zien. Een korte video van het portaal en een pasdag maakt kledingbeheer verkoopbaar.', 'bewijs', 'jessi', 2, 'open', 'leads_30d', 'marktanalyse stap 4, concurrentieanalyse 6 okt', 190, null),
  ('zet-demo-en-video-hoger-op-de-homepage', 'Zet demo en video hoger op de homepage', 'Tweede actie met de meeste opbrengst volgens de concurrentieanalyse: de zelf aanklikbare demo is uniek in de markt.', 'website', 'claude', 1, 'open', 'leads_30d', 'concurrentieanalyse 6 okt', 200, null),
  ('toon-het-aantal-google-reviews-zodra-het-er-genoeg-zijn', 'Toon het aantal Google-reviews zodra het er genoeg zijn', 'Bewust verborgen zolang het er weinig zijn; zodra het aantal geloofwaardig is in de bewijsbalk en referenties tonen.', 'bewijs', 'claude', 3, 'open', 'reviews_aantal', 'herontwerp 4 okt', 210, null),
  ('toon-een-prijsindicatie-per-startpakket', 'Toon een prijsindicatie per startpakket', 'Concurrenten winnen op zichtbare prijzen. Indicatie per pakket per medewerker, geen webshop; bedragen komen van Jessi.', 'website', 'claude', 1, 'open', 'lead_naar_offerte', 'concurrentieanalyse 6 okt', 220, null),
  ('zet-een-levertijdbelofte-boven-de-vouw', 'Zet een levertijdbelofte boven de vouw', 'De levertijd staat nu alleen in de FAQ; concurrenten maken er een belofte van. Levertijden komen van Jessi.', 'website', 'claude', 1, 'open', 'lead_naar_offerte', 'concurrentieanalyse 6 okt', 230, null),
  ('bevestig-levertijden-minimumaantallen-en-setadviezen', 'Bevestig levertijden, minimumaantallen en setadviezen', 'De cijfers op /bedrukken-borduren en de bedragen per pakket zijn ingeschat; Jessi bevestigt ze zodat de beloftes kloppen.', 'website', 'jessi', 1, 'open', 'lead_naar_offerte', 'website-bouw augustus, concurrentieanalyse 6 okt', 240, null),
  ('maak-een-duurzaamheidspagina-met-upv-textiel-en-keurmerken', 'Maak een duurzaamheidspagina met UPV Textiel en keurmerken', 'Concurrenten scoren op duurzaamheid. UPV Textiel geldt sinds 2023 (2026: 0,24 euro per kilo, 50 naar 75% hergebruik), met een antwoord op het advies om zonder borduursels in te kopen. Geen CSRD-verkooppraat.', 'website', 'claude', 2, 'open', 'lead_naar_offerte', 'concurrentieanalyse 6 okt, marktanalyse', 250, null),
  ('maak-een-beveiligingspagina-voor-het-portaal', 'Maak een beveiligingspagina voor het portaal', 'ecManage heeft ISO 27001; een pagina met 2FA, logboek, EU-hosting en AVG haalt het bezwaar weg bij grotere klanten.', 'website', 'claude', 2, 'open', 'lead_naar_offerte', 'concurrentieanalyse 6 okt', 260, null),
  ('bied-wij-komen-langs-met-een-pasdoos-als-eigen-aanbod', 'Bied ''wij komen langs met een pasdoos'' als eigen aanbod', 'Niemand lost het pasprobleem op en ''past het'' is de grootste wisseldrempel. Een tastbaar tussenaanbod met eigen pagina en CTA, inclusief monsters passen.', 'sales', 'claude', 2, 'open', 'leads_30d', 'marktanalyse stap 7', 270, null),
  ('toetsbare-belofte-en-kwalificatievraag-als-hoofd-cta', 'Toetsbare belofte en kwalificatievraag als hoofd-CTA', 'Hero ''Binnen 24 uur een offerte. Passen doen we bij jou op de zaak'' met reactietijd in de bewijsbalk.', 'website', 'claude', 1, 'klaar', 'leads_30d', 'marktanalyse stap 2', 280, now()),
  ('afspraak-en-offertepagina-als-kern-cta-herbouwen', 'Afspraak- en offertepagina als kern-CTA herbouwen', '/afspraak met stappenbalk en keuzetegels, /offerte over de volle breedte met Jessi-paneel.', 'website', 'claude', 1, 'klaar', 'lead_naar_offerte', 'ontwerpfeedback okt', 290, now()),
  ('pakketsamensteller-met-logo-preview-prominent-maken', 'Pakketsamensteller met logo-preview prominent maken', 'Sterkste conversietool: zelf samenstellen met logo live op het kledingstuk, met branche-prefill en lead-capture via ''ontwerp mailen''.', 'website', 'claude', 1, 'klaar', 'leads_30d', 'pakketconfigurator', 300, now()),
  ('onbelast-calculator-en-70-cm2-logocheck', 'Onbelast-calculator en 70 cm2 logocheck', 'Laat het fiscale voordeel van werkkleding met logo zien (WKR 2026). Geen concurrent heeft dit.', 'website', 'claude', 2, 'klaar', 'lead_naar_offerte', 'ronde 14', 310, now()),
  ('publieke-kledingbeheer-demo-met-leadpoort', 'Publieke kledingbeheer-demo met leadpoort', '/kledingbeheer/demo en één centrale gevulde demo-omgeving met wissel werkgever/werknemer, zodat Jessi zelf een demo geeft.', 'website', 'claude', 1, 'klaar', 'leads_30d', 'ronde 12, 15-17', 320, now()),
  ('kledingbeheer-verkopen-met-beeld', 'Kledingbeheer verkopen met beeld', 'Portaalscherm nagebouwd, uitvergrote fragmenten, grote getallen en ''werkt als app op je telefoon''.', 'website', 'claude', 2, 'klaar', 'leads_30d', 'marktanalyse stap 4', 330, now()),
  ('mobiele-site-strak-en-homepage-korter', 'Mobiele site strak en homepage korter', 'Geen zijwaarts schuiven meer, nieuw menu, kortere lange pagina''s en een vaste tabbalk in portaal en KMS.', 'website', 'claude', 2, 'klaar', 'leads_30d', 'ronde 22-23', 340, now()),
  ('leg-in-offerte-en-welkomstmail-uit-dat-het-portaal-een-app-i', 'Leg in offerte en welkomstmail uit dat het portaal een app is', 'De uitlegpagina /portaal/app staat in de uitnodigingsmail; nog toevoegen aan de offerte zodat klanten de webapp installeren.', 'klantbinding', 'claude', 3, 'open', 'portaal_klanten', 'pwa-app 4 okt', 350, null),
  ('tien-normeringspagina-s-gekoppeld-aan-het-assortiment', 'Tien normeringspagina''s gekoppeld aan het assortiment', 'EN ISO 20471, 11612, 343 en zeven andere, met beslisregel, klassentabel en producten uit het eigen assortiment.', 'seo', 'claude', 2, 'klaar', 'leads_30d', 'marktanalyse stap 5', 360, now()),
  ('branche-en-vakgebiedpagina-s-op-streekniveau', 'Branche- en vakgebiedpagina''s op streekniveau', 'Vakgebieden maal Achterhoek en zeven verdiepte branchepagina''s met functies, uitdagingen en FAQ.', 'seo', 'claude', 2, 'klaar', 'leads_30d', 'marktanalyse stap 6, ronde 14', 370, now()),
  ('beantwoord-de-branchevragen-voor-unieke-pagina-s', 'Beantwoord de branchevragen voor unieke pagina''s', 'Zes vragen per branche over sets, slijtage, normen en wat er misgaat; de setadviezen zijn nu inschattingen en worden pas uniek met Jessi''s praktijk.', 'content', 'jessi', 2, 'open', 'leads_30d', 'vragen Jessi branches 6 okt', 380, null),
  ('29-plaatspagina-s-binnen-24-km-met-echte-details', '29 plaatspagina''s binnen 24 km met echte details', 'Lokale pagina''s met bedrijventerreinen en km-afstand.', 'seo', 'claude', 2, 'klaar', 'leads_30d', 'seo-geo-plan ronde 12', 390, now()),
  ('breid-plaatspagina-s-uit-waar-rs-bedrijfskleding-staat', 'Breid plaatspagina''s uit waar RS Bedrijfskleding staat', 'RS heeft 50+ stadspagina''s; vul aan met plaatsen buiten de huidige 29 en verrijk bestaande met quotes en cases per plaats.', 'seo', 'claude', 3, 'open', 'leads_30d', 'concurrentieanalyse 6 okt', 400, null),
  ('localbusiness-schema-person-entiteit-jessi-en-llms-txt', 'LocalBusiness-schema, Person-entiteit Jessi en llms.txt', 'Werkgebied als cirkel van 24 km, Jessi als founder en auteur, llms.txt als feitenblad voor AI-antwoorden.', 'seo', 'claude', 2, 'klaar', 'leads_30d', 'seo-geo-plan ronde 12', 410, now()),
  ('kennisbank-met-commerciele-zoekintentie', 'Kennisbank met commerciële zoekintentie', '24 artikelen, waaronder ''leverancier kiezen in de Achterhoek'' en ''wat is een kledingbeheersysteem''.', 'content', 'claude', 2, 'klaar', 'leads_30d', 'seo-geo-plan ronde 12', 420, now()),
  ('schrijf-twee-kennisbankartikelen-per-maand-met-echte-prijzen', 'Schrijf twee kennisbankartikelen per maand met echte prijzen', 'Op vragen die klanten echt stellen (sets per medewerker, vervangtermijn, kosten per functie), met bandbreedtes van Frederiks zelf.', 'content', 'claude', 2, 'open', 'leads_30d', 'seo-geo-plan maand 2-4', 430, null),
  ('plaats-wekelijks-een-post-op-het-google-bedrijfsprofiel', 'Plaats wekelijks een post op het Google Bedrijfsprofiel', 'Een foto van een levering, passessie of borduurwerk per week houdt het profiel actief voor Maps.', 'content', 'jessi', 2, 'open', 'leads_30d', 'seo-geo-plan week 1-2', 440, null),
  ('stuur-een-persbericht-over-de-demo-en-het-kledingportaal', 'Stuur een persbericht over de demo en het kledingportaal', 'Naar Contact Midden en Achterhoek Nieuws; levert een lokale link en vermelding op.', 'content', 'claude', 3, 'open', 'leads_30d', 'seo-geo-plan maand 1-3', 450, null),
  ('verstuur-de-eerste-maandelijkse-nieuwsbrief', 'Verstuur de eerste maandelijkse nieuwsbrief', 'Editor, huisstijltemplate, double opt-in en batchverzending staan klaar; na Resend een vaste maandelijkse editie met tips, normnieuws en een case.', 'content', 'claude', 2, 'open', 'nieuwsbrief_abonnees', 'feedback Jessi 2 okt', 460, null),
  ('nieuwsbriefmodule-met-double-opt-in', 'Nieuwsbriefmodule met double opt-in', 'Blokkeneditor, testmail, afmeldlink, webversie en ingeplande verzending.', 'systeem', 'claude', 2, 'klaar', 'nieuwsbrief_abonnees', 'feedback Jessi 2 okt', 470, now()),
  ('sluit-aan-bij-lokale-ondernemersverenigingen', 'Sluit aan bij lokale ondernemersverenigingen', 'Ondernemersvereniging Hengelo, Ondernemend Bronckhorst en Achterhoek Ondernemers: netwerk plus lokale links.', 'netwerk', 'jessi', 2, 'open', 'leads_30d', 'seo-geo-plan maand 1-3', 480, null),
  ('benader-parkmanagement-verheulsweide-wijnbergen-en-a18', 'Benader parkmanagement Verheulsweide, Wijnbergen en A18', 'Een kanaal waar geen webshop bij kan: één ingang naar tientallen bedrijven op een terrein, bijvoorbeeld met een pasdag op locatie.', 'netwerk', 'jessi', 2, 'open', 'prospects_actief', 'marktanalyse stap 8', 490, null),
  ('sponsor-lokale-sportclubs-met-kleding-en-een-link', 'Sponsor lokale sportclubs met kleding en een link', 'Levert lokale links en zichtbaarheid; RS sponsort De Graafschap en NEC, Frederiks kan dichterbij op clubniveau.', 'netwerk', 'jessi', 3, 'open', 'leads_30d', 'seo-geo-plan, marktanalyse', 500, null),
  ('laat-frederiks-opnemen-in-dealerzoekers-van-merken', 'Laat Frederiks opnemen in dealerzoekers van merken', 'Leveranciersreferentie bij Tricorp en Snickers (en andere merken) geeft een sterke link en verwijzingen.', 'netwerk', 'jessi', 2, 'open', 'leads_30d', 'seo-geo-plan maand 1-3', 510, null),
  ('verstuur-de-eerste-batch-prospectbrieven-met-qr', 'Verstuur de eerste batch prospectbrieven met QR', 'Brievengenerator, persoonlijke kennismakingspagina met eigen logo en scanmelding staan klaar; QR werkt pas na de domeinkoppeling.', 'sales', 'jessi', 1, 'open', 'prospects_actief', 'feedback Jessi 2 okt', 520, null),
  ('bel-elke-qr-scan-binnen-een-dag-na', 'Bel elke QR-scan binnen een dag na', 'Na een scan ontstaat automatisch een beltaak; de opvolglijst en funnel tonen wie warm is.', 'sales', 'jessi', 1, 'open', 'lead_naar_offerte', 'feedback Jessi 2 okt', 530, null),
  ('brieven-met-qr-kennismakingspagina-en-scanfunnel', 'Brieven met QR, kennismakingspagina en scanfunnel', 'A4-blokeditor, batches, status per ontvanger, voorbeeldportaal met eigen logo en beltaak plus mail na scan.', 'systeem', 'claude', 2, 'klaar', 'prospects_actief', 'ronde 4', 540, now()),
  ('verrijk-de-resterende-prospects', 'Verrijk de resterende prospects', '222 Achterhoekse bedrijven geladen, maar ongeveer 150 nog zonder e-mail, telefoon of eigenaar; aanvullen en het bestand verder ophogen binnen de doelbranches.', 'sales', 'claude', 2, 'open', 'prospects_actief', 'roadmap prospects', 550, null),
  ('benader-de-grote-regionale-werkgevers', 'Benader de grote regionale werkgevers', 'Nedap, Royal Kaak, Kramp, NEDCON, Hosokawa, FrieslandCampina en Aviko; industrie en bouw (ca. 35.000 banen) verbruiken de meeste kleding, zorg (ca. 31.600) groeit stabiel.', 'sales', 'jessi', 2, 'open', 'prospects_actief', 'marktanalyse regio', 560, null),
  ('volg-elke-weblead-binnen-24-uur-op', 'Volg elke weblead binnen 24 uur op', 'De belofte staat op de site; de banner met ''Bel'' en wachttimer in het KMS helpt, maar de opvolging bepaalt lead naar offerte.', 'sales', 'jessi', 1, 'open', 'lead_naar_offerte', 'ronde 20', 570, null),
  ('geef-zelf-demo-s-aan-prospects-en-bestaande-klanten', 'Geef zelf demo''s aan prospects en bestaande klanten', 'Eén centrale demo-omgeving opent vanuit het KMS; inzetten in elk verkoopgesprek om kledingbeheer te verkopen.', 'sales', 'jessi', 2, 'open', 'lead_naar_offerte', 'ronde 15-17', 580, null),
  ('weblead-keten-met-herkomst-leadscore-en-rapportage-per-kanaa', 'Weblead-keten met herkomst, leadscore en rapportage per kanaal', 'Herkomst, leadscore op gedrag, conceptofferte, taak en melding, samenvoegen van dubbele leads en kanban.', 'systeem', 'claude', 1, 'klaar', 'leads_30d', 'ronde 4-6', 590, now()),
  ('activeer-de-mailcampagnes-na-resend', 'Activeer de mailcampagnes na Resend', 'Flowbouwer met 8 voorbeeldcampagnes en open/kliktracking staat klaar; kies 2 à 3 flows (welkom, offerte-opvolging, herbestelling) en zet ze aan.', 'sales', 'tim', 2, 'open', 'campagnes_actief', 'ronde 4', 600, null),
  ('visuele-campagnebouwer-met-triggers-en-rapportage', 'Visuele campagnebouwer met triggers en rapportage', 'Flowbouwer, doelen, 8 voorbeeldcampagnes en tracking.', 'systeem', 'claude', 2, 'klaar', 'campagnes_actief', 'ronde 4', 610, now()),
  ('online-afspraakplanner-gekoppeld-aan-de-leadketen', 'Online afspraakplanner gekoppeld aan de leadketen', '/afspraak met agenda-uitnodiging, herinnering, verzetlink en herkomst in de rapportage.', 'systeem', 'claude', 2, 'klaar', 'leads_30d', 'ronde 6', 620, now()),
  ('zet-bestaande-klanten-in-het-portaal', 'Zet bestaande klanten in het portaal', '176 klanten staan in het KMS; geef werkgevers toegang en maak werknemers met maten aan zodat ze binnen het systeem herbestellen.', 'klantbinding', 'jessi', 1, 'open', 'portaal_klanten', 'portaal-toegang-proces', 640, null),
